237 | base::flat_set<url::Origin> GetIsolatedContextOriginSetFromFlag() {
238 |   std::string cmdline_origins(
239 |       base::CommandLine::ForCurrentProcess()->GetSwitchValueASCII(
240 |           switches::kIsolatedContextOrigins));
241 | 
242 |   std::vector<std::string_view> origin_strings = base::SplitStringPiece(
243 |       cmdline_origins, ",", base::TRIM_WHITESPACE, base::SPLIT_WANT_NONEMPTY);
244 | 
245 |   base::flat_set<url::Origin> origin_set;
246 |   for (std::string_view origin_string : origin_strings) {
247 |     url::Origin allowed_origin = url::Origin::Create(GURL(origin_string));
248 |     if (!allowed_origin.opaque()) {
249 |       origin_set.insert(allowed_origin);
250 |     } else {
251 |       LOG(ERROR) << "Error parsing IsolatedContext origin: " << origin_string;
252 |     }
253 |   }
254 |   return origin_set;
255 | }
