427 | bool ShellContentBrowserClient::IsHandledURL(const GURL& url) {
428 |   if (!url.is_valid()) {
429 |     return false;
430 |   }
431 |   constexpr auto kProtocolList = base::MakeFixedFlatSet<std::string_view>({
432 |       url::kHttpScheme,
433 |       url::kHttpsScheme,
434 |       url::kWsScheme,
435 |       url::kWssScheme,
436 |       url::kBlobScheme,
437 |       url::kFileSystemScheme,
438 |       kChromeUIScheme,
439 |       kChromeUIUntrustedScheme,
440 |       kChromeDevToolsScheme,
441 |       url::kDataScheme,
442 |       url::kFileScheme,
443 |   });
444 | 
445 |   return kProtocolList.contains(url.scheme());
446 | }
