165 |   // Parses the header from a string and calls SetHeader() with it.  This string
166 |   // should not contain any CRLF.  As per RFC7230 Section 3.2, the format is:
167 |   //
168 |   // header-field   = field-name ":" OWS field-value OWS
169 |   //
170 |   // field-name     = token
171 |   // field-value    = *( field-content / obs-fold )
172 |   // field-content  = field-vchar [ 1*( SP / HTAB ) field-vchar ]
173 |   // field-vchar    = VCHAR / obs-text
174 |   //
175 |   // obs-fold       = CRLF 1*( SP / HTAB )
176 |   //                ; obsolete line folding
177 |   //                ; see Section 3.2.4
178 |   //
179 |   // AddHeaderFromString() will trim any LWS surrounding the
180 |   // field-content.
181 |   void AddHeaderFromString(std::string_view header_line);
